class Solution:
    def getSum(self, a: int, b: int) -> int:
        MASK = 0xFFFFFFFF          # keep values to 32 bits
        MAX_INT = 0x7FFFFFFF       # largest positive 32-bit value
        a &= MASK
        b &= MASK
        while b:
            carry = (a & b) << 1
            a = (a ^ b) & MASK     # bitwise sum without carry
            b = carry & MASK       # carry becomes the new addend
        # a is now an unsigned 32-bit pattern; reinterpret as signed
        return a if a <= MAX_INT else ~(a ^ MASK)

